('157', '4', 'page_subtitle', 'text', 'Proprietary Technology', '10'),
('158', '4', 'page_title', 'text', 'Advanced Packaging Innovations & Security Features', '20'),
('159', '4', 'page_intro', 'text', 'Protecting patient safety, brand integrity, and supply chain authenticity through cutting-edge packaging engineering.', '30'),
('160', '4', 'coldseal_badge', 'text', 'PATENT-PENDING ECO INNOVATION', '40'),
('161', '4', 'coldseal_title', 'text', 'ColdSeal Blister Wallet', '50'),
('162', '4', 'coldseal_desc', 'richtext', '<p>ColdSeal Blister Wallet is a pressure-sealed (non-heat-sealed) blister packaging system encapsulated between paperboard layers.</p><ul style=\"padding-left:1.25rem; color:var(--text-body); margin: 1rem 0;\"><li><strong>50% Material Reduction:</strong> Reduces plastic and aluminum foil usage by up to 50% compared to traditional rigid blisters.</li><li><strong>Child-Resistant & Senior-Friendly:</strong> Engineered latch mechanisms compliant with safety standards.</li><li><strong>Dose Compliance Tracking:</strong> Integrated calendar layout for patient compliance adherence.</li><li><strong>Available Formats:</strong> Wallet format, Box format, and Card format.</li><li><strong>Applications:</strong> Tablets/capsules, pre-filled syringes/pens, ampoules/vials, droppers.</li></ul>', '60'),
('163', '4', 'coldseal_image', 'image', 'assets/images/coldseal.jpg', '70'),
('164', '4', 'engravix_badge', 'text', 'OPTICAL ANTI-COUNTERFEIT SECURITY', '80'),
('165', '4', 'engravix_title', 'text', '3D-Engravix™ Optical Technology', '90'),
('166', '4', 'engravix_desc', 'richtext', '<p>3D-Engravix™ is an advanced optical security feature integrated directly onto pharmaceutical Printed Cartons during manufacturing.</p><p><strong>Zero Equipment Needed:</strong> Authentication is 100% visual under ambient light. Pharmacists, distributors, healthcare professionals, and patients require NO scanner, smartphone app, or reader device.</p><h4 style=\"margin-top:1rem;\">Authentication Principles:</h4><ol style=\"padding-left:1.25rem; color:var(--text-body); font-size:0.9rem;\"><li><strong>Micro-Optic Motion:</strong> Spinning blade, flowing motion, and travelling light effects when tilted.</li><li><strong>Flip Effect:</strong> Seamless visual transformation between objects when package is tilted vertically.</li><li><strong>Seal-Base Color Shift:</strong> Angle-dependent color shift (e.g. violet-purple to emerald-green shift).</li></ol>', '100'),
