('222', '12', 'page_title', 'text', 'Privacy Policy', '10'),
('223', '12', 'page_body', 'richtext', '<p>Prince Art Packages (Private) Limited respects your privacy and is committed to protecting your personal information. This Privacy Policy outlines how we handle information collected through our website, quote requests, and client communications.</p><p>We collect basic business contact details (name, email, company, phone) submitted voluntarily through our quotation and inquiry forms. This information is strictly used for commercial communication, technical specification evaluations, and client order execution. We do not sell or lease your information to third parties.</p>', '20'),
('224', '13', 'page_title', 'text', 'Terms & Conditions', '10'),
('225', '13', 'page_body', 'richtext', '<p>Welcome to the official website of Prince Art Packages (Private) Limited. By accessing and using this website, you agree to comply with and be bound by the terms and conditions outlined herein.</p><p>All content, specifications, logos, and proprietary features (including 3D-Engravix™ and ColdSeal designs) are intellectual property of Prince Art Packages (Private) Limited. Unauthorized copying, reproduction, or redistribution is strictly prohibited.</p>', '20'),
('226', '11', 'page_subtitle', 'text', 'PACKAGING INSIGHTS & TECHNICAL ARTICLES', '10'),
('227', '11', 'page_title', 'text', 'Pharmaceutical Packaging Insights', '20'),
('228', '11', 'page_intro', 'text', 'Technical publications, regulatory compliance guidelines, and anti-counterfeiting innovations from Prince Art Packages (Private) Limited.', '30'),
('229', '1', 'hero_title', 'text', 'Precision Pharmaceutical Secondary Packaging Engineered for Global Audit Compliance', '10'),
('230', '1', 'hero_subtitle', 'text', 'ISO 9001:2015 certified manufacturer of Printed Cartons, leaf-inserts, printed labels, ColdSeal blister wallets, and 3D-Engravix™ optical anti-counterfeit security packaging based in Korangi Creek Industrial Park, Karachi.', '20'),
('231', '1', 'hero_image', 'image', 'assets/images/engravix.jpg', '25'),
('232', '1', 'capability_intro', 'text', 'Purpose-engineered paperboard packaging, precision inserts, self-adhesive roll labels, and proprietary security features.', '80'),
('257', '2', 'intro_subtitle', 'text', 'Company Introduction', '32'),
('258', '2', 'intro_title', 'text', 'Who We Are', '33'),
('259', '2', 'intro_overview', 'richtext', 'Prince Art Packages is a pharmaceutical secondary packaging manufacturer focused on delivering reliable, precision-engineered <a href=\"products.php\" class=\"text-link\">pharmaceutical packaging solutions</a> for pharmaceutical and healthcare companies.', '34'),
('260', '2', 'intro_narrative', 'text', 'Operating two cGMP-aligned manufacturing plants in Korangi Creek Industrial Park, Karachi, we combine more than 40 years of industrial heritage with state-of-the-art multi-color offset printing, precision converting, and in-house laboratory quality controls to ensure zero-defect secondary packaging for regulated domestic and export healthcare markets.', '35'),
('261', '2', 'pillar_1_title', 'text', '40+ Years of Industry Experience', '36'),
('262', '2', 'pillar_1_desc', 'text', 'Originally founded over 40 years ago as Prince Art Press, our company has grown through four continuous decades of technical innovation into Prince Art Packages (Private) Limited—delivering unmatched consistency and industry trust.', '37'),
('263', '2', 'pillar_2_title', 'text', 'Pharmaceutical Packaging Specialization', '38'),
('264', '2', 'pillar_2_desc', 'text', 'Our primary business is 100% focused on pharmaceutical secondary packaging. Production lines are purpose-built to eliminate cross-contamination, prevent mix-ups, and run seamlessly on high-speed automated cartoning lines.', '39'),
('265', '2', 'pillar_3_title', 'text', 'Dual Manufacturing Locations', '40'),
('266', '2', 'pillar_3_desc', 'text', 'Operating two modern industrial facilities in Korangi Creek Industrial Park, Karachi (Unit 1: Sector 38 and Unit 2: Plot 239 Main Korangi Creek Road), providing built-in production redundancy and risk-mitigated supply chains.', '41'),
('267', '2', 'pillar_4_title', 'text', 'Comprehensive Product Portfolio', '42'),
('268', '2', 'pillar_4_desc', 'text', 'Manufacturing Printed Cartons (reverse tuck, crash-lock), 27–60gsm prescribing inserts/outserts, printed self-adhesive roll labels, ColdSeal blister wallets, tamper-evident seals, and 3D-Engravix™ security packaging.', '43'),
('269', '2', 'pillar_5_title', 'text', 'Regulated Healthcare Markets', '44'),
('270', '2', 'pillar_5_desc', 'text', 'Proudly supplying commercial pharmaceutical manufacturers (solid orals, parenterals, syrups), OTC and consumer healthcare brands, hospitals, medical device companies, and regulated international export markets.', '45'),
('271', '2', 'pillar_6_title', 'text', 'Uncompromising Quality Commitment', '46'),
('272', '2', 'pillar_6_desc', 'text', 'ISO 9001:2015 certified (Cert No. KQ.2025.5393 - ASCERT) and FSC Chain of Custody certified (FSC-C222205). Governed by cGMP line clearance, batch traceability, and full in-house testing laboratory verification.', '47'),
