('297', '2', 'qc_sec_subtitle', 'text', 'Quality & Compliance', '130'),
('298', '2', 'qc_sec_title', 'text', 'Quality and Compliance at the Core of Our Operations', '131'),
('299', '2', 'qc_sec_intro', 'richtext', 'Pharmaceutical packaging demands zero error tolerance. We place <a href=\"quality.php\" class=\"text-link\">quality and compliance</a> at the core of our operations, providing procurement leaders, QA managers, and regulatory auditors with absolute confidence through internationally verified certifications, strict cGMP line clearance, and in-house laboratory testing.', '132'),
('300', '2', 'qc_cgmp_title', 'text', 'cGMP Compliance', '133'),
('301', '2', 'qc_cgmp_desc', 'text', 'Strict line clearance protocols between production batches, air-controlled production bays, segregated raw material staging, and complete operator hygiene controls to eliminate cross-contamination and packaging mix-ups.', '134'),
('302', '2', 'qc_iso_title', 'text', 'ISO 9001:2015 Certification', '135'),
('303', '2', 'qc_iso_desc', 'text', 'Certified Quality Management System governing our entire manufacturing process from virgin paperboard procurement to precision offset printing, die-cutting, inspection, and customer delivery.', '136'),
